head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil30406";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil30406.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — ymd, today, lastResvDay, corpUsrTpCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_80", fn: function(){ return ((dlt_weekDayList.getCellData(0, "day") ?? (() => { throw new Error("unresolved:" + "day.day"); })()) === '' || (String(((dlt_weekDayList.getCellData(0, "day") ?? (() => { throw new Error("unresolved:" + "day.day"); })())) == null ? '' : ((dlt_weekDayList.getCellData(0, "day") ?? (() => { throw new Error("unresolved:" + "day.day"); })()))).length === 0)); } }, { id: "c_otherwise_82", fn: function(){ return (!(((dlt_weekDayList.getCellData(0, "day") ?? (() => { throw new Error("unresolved:" + "day.day"); })()) === '' || (String(((dlt_weekDayList.getCellData(0, "day") ?? (() => { throw new Error("unresolved:" + "day.day"); })())) == null ? '' : ((dlt_weekDayList.getCellData(0, "day") ?? (() => { throw new Error("unresolved:" + "day.day"); })()))).length === 0)))); } }, { id: "c_when_84", fn: function(){ return ((dlt_weekDayList.getCellData(0, "holiday") ?? (() => { throw new Error("unresolved:" + "day.holiday"); })()) === true); } }, { id: "c_otherwise_86", fn: function(){ return (!(((dlt_weekDayList.getCellData(0, "holiday") ?? (() => { throw new Error("unresolved:" + "day.holiday"); })()) === true))); } }, { id: "c_when_88", fn: function(){ return ((dma_pageContext.get("ymd") ?? "") <= (dma_pageContext.get("today") ?? "") || (dma_pageContext.get("ymd") ?? "") >= (dma_pageContext.get("lastResvDay") ?? "")); } }, { id: "c_otherwise_90", fn: function(){ return (!(((dma_pageContext.get("ymd") ?? "") <= (dma_pageContext.get("today") ?? "") || (dma_pageContext.get("ymd") ?? "") >= (dma_pageContext.get("lastResvDay") ?? "")))); } }, { id: "c_when_93", fn: function(){ return ((dma_schedule.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "schedule.reservStatTpCd"); })()) === '2'); } }, { id: "c_when_95", fn: function(){ return ((dma_schedule.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "schedule.reservStatTpCd"); })()) === '3'); } }, { id: "c_when_111_txt", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '11'); } }, { id: "c_when_112_txt", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '21'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_77", entity: "dlt_weekDayList", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return String(v("day")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("day")); } }, { childId: "__rc2", fn: function (v, i) { return String(v("day")); } }, { childId: "__rc3", fn: function (v, i) { return String(v("day")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb5", fn: function () { return " " + String(String(dma_schedule.get("useStrtDdtm")).substring(8, 10)) + " ~ " + String(String(dma_schedule.get("useEndDdtm")).substring(8, 10)) + "시 "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fn_findSchedules, tx_fn_searchList) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_searchList_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchList_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30406.btn_searchList_onclick' }); }
};

/**
 * @method
 * @name slc_year01_onchange
 * @description slc_year01 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_year01_onchange = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.schedules1(selfVar.value)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30406.slc_year01_onchange' }); }
};

/**
 * @method
 * @name span_onclick
 * @description 「${month.name}월」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.span_onclick = async function(e){
    try {
        await scwin.schedules2('' + dma_month.get("code") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30406.span_onclick' }); }
};

/**
 * @method
 * @name span_92_onclick
 * @description span_92 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.span_92_onclick = async function(e){
    try {
        await scwin.smartBzCenterResv((String(((dma_pageContext.get("ymd") ?? "")) == null ? '' : ((dma_pageContext.get("ymd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ymd") ?? "")) == null ? '' : ((dma_pageContext.get("ymd") ?? "")))),'','','')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30406.span_92_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_findSchedules
 * @description find Schedules 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_findSchedules = async function () {
    const sbmOptions = {
        id: "tx_fn_findSchedules",
        method: "post",
        action: "/issue/IRroom.do",
        ref: "dma_findSchedulesReq",
        target: "dlt_weekDayList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/issue/IRroom.do",
        ref: "dma_searchListReq",
        target: "dlt_weekDayList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_smartBzCenterResv
 * @description smart Bz Center Resv 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_smartBzCenterResv = async function () {
    const sbmOptions = {
        id: "tx_fn_smartBzCenterResv",
        method: "post",
        action: "/issue/IRroom.do",
        ref: "dma_smartBzCenterResvReq",
        target: "dlt_weekDayList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name schedules1
 * @description schedules1 처리
 * @param {*} year year
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.schedules1 = async function (year) {
    await scwin.findSchedules();
};

/**
 * @method
 * @name schedules2
 * @description schedules2 처리
 * @param {*} month month
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.schedules2 = async function (month) {
    document.all["span" + $c.util.getComponent('dma_findSchedulesReq').get('month')].className = "";
    document.all["span" + month].className = "thisMonth";
    $c.util.getComponent('dma_findSchedulesReq').set('month', month);
    await scwin.findSchedules();
};

/**
 * @method
 * @name findSchedules
 * @description find Schedules 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findSchedules = async function () {
    const frm = (document.smartBzCenterForm || { elements: [] });
    $c.util.getComponent('dma_findSchedulesReq').set('method', "searchSmartBzCenterResv");
    frm.action = "/issue/IRroom.do";
    await scwin.tx_fn_findSchedules();
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    const frm = (document.smartBzCenterForm || { elements: [] });
    $c.util.getComponent('dma_findSchedulesReq').set('method', "searchSmartBzCenterResv");
    frm.action = "/issue/IRroom.do";
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name smartBzCenterResv
 * @description smart Bz Center Resv 처리
 * @param {*} ymd ymd
 * @param {*} applNo applNo
 * @param {String} reservStatTpCd reservStatTpCd
 * @param {String} useStrtDd useStrtDd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.smartBzCenterResv = async function (ymd, applNo, reservStatTpCd, useStrtDd) {
    const frm = (document.smartBzCenterForm || { elements: [] });
    $c.util.getComponent('dma_findSchedulesReq').set('calDd', ymd);
    $c.util.getComponent('dma_findSchedulesReq').set('applNo', applNo);
    if (applNo != null && applNo !== '') {
        if (reservStatTpCd === '2' || reservStatTpCd === '3' || reservStatTpCd === '4' || reservStatTpCd === '5') {
            $c.util.getComponent('dma_findSchedulesReq').set('method', "goSmartBzCenterResv");
        } else {
            if (useStrtDd <= (String(((dma_pageContext.get("today") ?? "")) == null ? '' : ((dma_pageContext.get("today") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("today") ?? "")) == null ? '' : ((dma_pageContext.get("today") ?? ""))))) {
                $c.util.getComponent('dma_findSchedulesReq').set('method', "goSmartBzCenterResv");
            } else {
                $c.util.getComponent('dma_findSchedulesReq').set('method', "marketSquarePriAgree");
            }
        }
    } else {
        $c.util.getComponent('dma_findSchedulesReq').set('method', "marketSquarePriAgree");
    }
    frm.action = "/issue/IRroom.do";
    const nr = await scwin.tx_fn_smartBzCenterResv();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil30407/jldfil30407.xml", { "calDd": ymd, "applNo": applNo, "method": "goSmartBzCenterResv" });
    }
};
